const box=document.querySelector('#intelList'),note=box.nextElementSibling;
const refresh=document.createElement('button');refresh.textContent='刷新';refresh.className='more';refresh.setAttribute('aria-label','刷新官方公告');box.parentElement.querySelector('.panel-head').append(refresh);
async function update(){refresh.disabled=true;note.textContent='正在读取上期所官方公告…';try{const r=await fetch('/api/news');if(!r.ok)throw Error();const data=await r.json();box.replaceChildren();for(const item of data.items||[]){const a=document.createElement('a');a.className='intel-item';a.href=item.url;a.target='_blank';a.rel='noopener noreferrer';const time=document.createElement('small');time.textContent=item.date.slice(5);const title=document.createElement('span');title.textContent=item.title;a.append(time,title);box.append(a)}note.textContent=data.items?.length?(data.stale?'缓存过期 · ':'官方公告 · ')+new Date(data.fetchedAt).toLocaleTimeString('zh-CN')+' 抓取 · 标题索引':data.error||'无公告';}catch{note.textContent='官方公告加载失败，未用演示新闻补齐'}finally{refresh.disabled=false}}
refresh.onclick=update;update();
